public class MoneyUtil {

    public static long parseToCents(String amount) {
        if (amount == null) throw new IllegalArgumentException("INVALID AMOUNT");
        try {
            BigDecimal bd = new BigDecimal(amount.trim());
            long cents = bd.multiply(new BigDecimal("100")).setScale(0, RoundingMode.HALF_UP).longValueExact();
            if (cents <= 0) throw new IllegalArgumentException("INVALID AMOUNT: " + amount);
            return cents;
        } catch (NumberFormatException | ArithmeticException e) {
            throw new IllegalArgumentException("INVALID AMOUNT: " + amount);
        }
    }

    public static String formatFromCents(long cents) {
        long whole = cents / 100;
        long frac = Math.abs(cents % 100);
        return String.format("%d.%02d", whole, frac);
    }
}

